  /* General styles and desktop-specific styles */
  @media only screen and (min-width: 750px) {
    .product--thumbnail_slider .thumbnail-slider {
      display: grid !important;
      grid-template-columns: repeat(2, 1fr) !important;
      gap: 8px;
      align-items: start !important;
    }

    .thumbnail-slider .thumbnail-list.slider--tablet-up {
      display: grid !important;
      grid-template-columns: repeat(2, 80px) !important;
      grid-auto-rows: 120px !important;
      gap: 8px !important;
      padding: 0 !important;
      width: 168px !important;
      min-width: 168px !important;
      overflow: visible !important;
    }

    .thumbnail.global-media-settings img {
      width: 80px !important;
      height: 120px !important;
      object-fit: contain !important;
      border-radius: 8px !important;
    }

    .thumbnail-list.slider--tablet-up .thumbnail-list__item.slider__slide {
      height: 120px !important;
      width: 80px !important;
    }

    .thumbnail-slider button.slider-button.slider-button--prev,
    .thumbnail-slider button.slider-button.slider-button--next,
    .slider-buttons--product-stepper button.slider-button.slider-button--prev,
    .slider-buttons--product-stepper button.slider-button.slider-button--next {
      display: none !important;
    }

    media-gallery.product__column-sticky:has(.thumbnail-slider) {
      display: grid !important;
      grid-template-columns: 175px 1fr !important;
      gap: 5px !important;
    }

    .thumbnail-slider.slider-mobile-gutter.quick-add-hidden {
      order: -1 !important;
    }

    .thumbnail[aria-current] {
      border-radius: 8px !important;
    }
  }

  /* Styles for both desktop and mobile */
  .card--card.gradient, .card__inner.gradient {
    background: transparent !important;
  }

  .card .media {
    border-radius: 15px !important;
  }

  button#checkout {
    background-color: #28a745;
    color: #ffffff;
    border: none;
    padding: 15px 20px;
    font-size: 18px;
    font-weight: bold;
    text-transform: uppercase;
    cursor: pointer;
    transition: background-color 0.3s ease;
  }

  button#checkout:hover {
    background-color: #218838;
  }

  body.gradient {
    background: #white;
  }

  body {
    background-color: #FFFFFF;
    color: #000000;
    font-family: Arial, sans-serif;
  }

  /* Category nav tabs styling */
  .collection-category-nav__tabs {
    display: flex;
    flex-wrap: wrap;
    gap: 0.8rem;
    padding: 1rem 0;
    margin: 0;
  }
  .collection-category-nav__tab {
    color: #121212 !important;
    background: #f3f3f3;
    padding: 8px 18px;
    border-radius: 25px;
    font-size: 13px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    text-decoration: none;
    transition: background-color 0.2s ease, color 0.2s ease;
    display: inline-block;
  }
  .collection-category-nav__tab:hover {
    background: #121212;
    color: #ffffff !important;
  }
  .collection-category-nav__tab.is-active {
    background: #121212;
    color: #ffffff !important;
  }

  /* Mobile: collection page adjustments */
  @media screen and (max-width: 749px) {
    /* Hide breadcrumbs on mobile — title already shows the page name */
    .collection-breadcrumb {
      display: none !important;
    }
    /* Small gap between search bar and pills */
    .page-width--collection-breadcrumbs {
      padding-top: 10px;
      margin-top: 0;
    }
    /* Horizontal scroll for pills */
    .collection-category-nav__tabs-wrap {
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none; /* Firefox */
      margin: 0 -1.5rem;
      padding: 0 1.5rem;
    }
    .collection-category-nav__tabs-wrap::-webkit-scrollbar {
      display: none; /* Chrome/Safari */
    }
    .collection-category-nav__tabs {
      flex-wrap: nowrap;
      padding: 0.5rem 0;
      gap: 0.6rem;
    }
    .collection-category-nav__tab {
      white-space: nowrap;
      flex-shrink: 0;
      padding: 6px 14px;
      font-size: 12px;
    }
  }

  /* Establish the mobile heading before body styles load. */
  @media (max-width: 767px) {
    /* Show the existing heading; keep the compact mobile banner. */
    #MainContent .collection-hero {
        display: block !important;
    }

    #MainContent .collection-hero__image-container,
    #MainContent .collection-hero__text-wrapper > :not(.collection-hero__title) {
        display: none !important;
    }

    /* Remove space reserved for the hidden collection image. */
    #MainContent .collection-hero.collection-hero--with-image,
    #MainContent .collection-hero .collection-hero__text-wrapper {
        padding: 0;
    }

    #MainContent .collection-hero .collection-hero__inner {
        padding-bottom: 0;
    }

    #MainContent .collection-hero .collection-hero__text-wrapper {
        flex-basis: 100%;
    }

    #MainContent .collection-hero .collection-hero__title {
        margin: 1.8rem auto 0;
        max-width: 24ch;
        text-wrap: balance;
    }
  }

  header {
    padding: 10px 20px; /* Adjust as needed */
    background-color: #FDFFFE;
    text-align: center;
    border-bottom: none;
    width: 100%;
    margin: 0; /* Ensure no unwanted margins */
    box-sizing: border-box; /* Ensure box-sizing is set correctly */
  }

  .card__title {
    display: -webkit-box;
    -webkit-line-clamp: 4;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .card__heading a,
  .cart__product-title,
  .checkout__product-title {
    display: inline-block;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @media screen and (min-width: 768px) {
    .card__heading a,
    .cart__product-title,
    .checkout__product-title {
      max-width: 365px;
      font-size: 14px;
    }
    /* Adjust product image size */
.product-grid__image-wrapper {
    height: 450px; /* Increase or decrease as needed */
    overflow: hidden; /* Prevents images from overflowing */
}

.product-grid__image-wrapper img {
    height: 100%; /* Ensures the image fits the new height */
    width: auto; /* Maintains the image aspect ratio */
}

    .template-product .product__title {
      max-width: none;
      white-space: normal;
      overflow: visible;
      text-overflow: ellipsis;
    }
  }

@media screen and (max-width: 767px) {
    .card__heading a,
    .cart__product-title,
    .checkout__product-title {
        display: -webkit-box; /* Necessary for webkit-line-clamp to work */
        -webkit-line-clamp: 1; /* Limit to 2 lines */
        -webkit-box-orient: vertical; /* Box orientation set to vertical */
        text-overflow: ellipsis; /* Add ellipsis for truncated text */
        overflow: hidden; /* Hide text that overflows */
        white-space: normal; /* Allow text to wrap */
        max-width: 100%; /* Let the title take full width */
        font-size: 10px !important; /* Ensure font size is applied */
        line-height: 1.2;

    }

}



