    outline: none;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.5px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: max-height 0.2s ease-out, padding 0.2s ease-out;
    background-color: transparent;
    color: #333;
  }
  .collapsible:last-of-type {
    border-bottom: 1px solid #eee;
  }

  .collapsible svg {
    margin-right: 10px;
  }

  .toggle-icon {
